Here is the commit message:
ext4: fix memory leak in ext4_ext_shift_extents()

In ext4_ext_shift_extents(), if the extent is NULL in the while loop, the
function returns immediately without releasing the path obtained via
ext4_find_extent(), leading to a memory leak.

Fix this by jumping to the out label to ensure the path is properly
released.

Fixes: a18ed359bdddc ("ext4: always check ext4_ext_find_extent result")
Signed-off-by: Zilin Guan <zilin@seu.edu.cn>
Reviewed-by: Zhang Yi <yi.zhang@huawei.com>
Reviewed-by: Baokun Li <libaokun1@huawei.com>
Link: https://patch.msgid.link/20251225084800.905701-1-zilin@seu.edu.cn
Signed-off-by: Theodore Ts'o <tytso@mit.edu>
Cc: stable@kernel.org

Here is the root cause:
In ext4_ext_shift_extents(), when the extent is NULL (indicating an unexpected hole), the function directly returns -EFSCORRUPTED without releasing the path allocated by ext4_find_extent(), causing a memory leak. The fix changes the return to a goto to the cleanup label.

Here is the patch:
  */
 static int
 ext4_ext_shift_extents(struct inode *inode, handle_t *handle,
 		       ext4_lblk_t start, ext4_lblk_t shift,
 		       enum SHIFT_DIRECTION SHIFT)
 {
 	struct ext4_ext_path *path;
 	int ret = 0, depth;
 	struct ext4_extent *extent;
 	ext4_lblk_t stop, *iterator, ex_start, ex_end;
 	ext4_lblk_t tmp = EXT_MAX_BLOCKS;

 	/* Let path point to the last extent */
 	path = ext4_find_extent(inode, EXT_MAX_BLOCKS - 1, NULL,
 				EXT4_EX_NOCACHE);
 	if (IS_ERR(path))
 		return PTR_ERR(path);

 	depth = path->p_depth;
 	extent = path[depth].p_ext;
 	if (!extent)
 		goto out;

 	stop = le32_to_cpu(extent->ee_block);

        /*
 	* For left shifts, make sure the hole on the left is big enough to
 	* accommodate the shift.  For right shifts, make sure the last extent
 	* won't be shifted beyond EXT_MAX_BLOCKS.
 	*/
 	if (SHIFT == SHIFT_LEFT) {
 		path = ext4_find_extent(inode, start - 1, path,
 					EXT4_EX_NOCACHE);
 		if (IS_ERR(path))
 			return PTR_ERR(path);
 		depth = path->p_depth;
 		extent =  path[depth].p_ext;
 		if (extent) {
 			ex_start = le32_to_cpu(extent->ee_block);
 			ex_end = le32_to_cpu(extent->ee_block) +
 				ext4_ext_get_actual_len(extent);
 		} else {
 			ex_start = 0;
 			ex_end = 0;
 		}

 		if ((start == ex_start && shift > ex_start) ||
 		    (shift > start - ex_end)) {
 			ret = -EINVAL;
 			goto out;
 		}
 	} else {
 		if (shift > EXT_MAX_BLOCKS -
 		    (stop + ext4_ext_get_actual_len(extent))) {
 			ret = -EINVAL;
 			goto out;
 		}
 	}

 	/*
 	 * In case of left shift, iterator points to start and it is increased
 	 * till we reach stop. In case of right shift, iterator points to stop
 	 * and it is decreased till we reach start.
 	 */
 again:
 	ret = 0;
 	if (SHIFT == SHIFT_LEFT)
 		iterator = &start;
 	else
 		iterator = &stop;

 	if (tmp != EXT_MAX_BLOCKS)
 		*iterator = tmp;

 	/*
 	 * Its safe to start updating extents.  Start and stop are unsigned, so
 	 * in case of right shift if extent with 0 block is reached, iterator
 	 * becomes NULL to indicate the end of the loop.
 	 */
 	while (iterator && start <= stop) {
 		path = ext4_find_extent(inode, *iterator, path,
 					EXT4_EX_NOCACHE);
 		if (IS_ERR(path))
 			return PTR_ERR(path);
 		depth = path->p_depth;
 		extent = path[depth].p_ext;
 		if (!extent) {
 			EXT4_ERROR_INODE(inode, "unexpected hole at %lu",
 					 (unsigned long) *iterator);
-			return -EFSCORRUPTED;
+			ret = -EFSCORRUPTED;
+			goto out;
 		}
 		if (SHIFT == SHIFT_LEFT && *iterator >
 		    le32_to_cpu(extent->ee_block)) {
 			/* Hole, move to the next extent */
 			if (extent < EXT_LAST_EXTENT(path[depth].p_hdr)) {
 				path[depth].p_ext++;
 			} else {
 				*iterator = ext4_ext_next_allocated_block(path);
 				continue;
 			}
 		}

 		tmp = *iterator;
 		if (SHIFT == SHIFT_LEFT) {
 			extent = EXT_LAST_EXTENT(path[depth].p_hdr);
 			*iterator = le32_to_cpu(extent->ee_block) +
 					ext4_ext_get_actual_len(extent);
 		} else {
 			extent = EXT_FIRST_EXTENT(path[depth].p_hdr);
 			if (le32_to_cpu(extent->ee_block) > start)
 				*iterator = le32_to_cpu(extent->ee_block) - 1;
 			else if (le32_to_cpu(extent->ee_block) == start)
 				iterator = NULL;
 			else {
 				extent = EXT_LAST_EXTENT(path[depth].p_hdr);
 				while (le32_to_cpu(extent->ee_block) >= start)
 					extent--;

 				if (extent == EXT_LAST_EXTENT(path[depth].p_hdr))
 					break;

 				extent++;
 				iterator = NULL;
 			}
 			path[depth].p_ext = extent;
 		}
 		ret = ext4_ext_shift_path_extents(path, shift, inode,
 				handle, SHIFT);
 		/* iterator can be NULL which means we should break */
 		if (ret == -EAGAIN)
 			goto again;
 		if (ret)
 			break;
 	}
 out:
 	ext4_free_ext_path(path);
 	return ret;
 }



